import{_ as a,o as s,c as t,X as o}from"./chunks/framework.pSp8ynCZ.js";const h=JSON.parse('{"title":"Data and execution model","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/concepts.md","filePath":"concepts.md"}'),n={name:"rust/docs/concepts.md"};function d(r,e,c,i,l,p){return s(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="data-and-execution-model" tabindex="-1">Data and execution model <a class="header-anchor" href="#data-and-execution-model" aria-label="Permalink to &quot;Data and execution model&quot;">​</a></h1><h2 id="matrices-chunks-records-and-pages" tabindex="-1">Matrices, chunks, records, and pages <a class="header-anchor" href="#matrices-chunks-records-and-pages" aria-label="Permalink to &quot;Matrices, chunks, records, and pages&quot;">​</a></h2><p>A <code>.cpk</code> file holds one matrix. Rows are divided into chunks, each sharing a set of coding models and an optional column permutation. Each row has an independently decodable record; empty rows may have no record bytes. Records are packed onto pages so a reader needs only the pages covering its record and the chunk&#39;s metadata.</p><p>Independent decoding removes dependencies between records. It still requires the matching chunk metadata and decode tables. Neighboring records may share a page.</p><table tabindex="0"><thead><tr><th>Object</th><th>Meaning</th></tr></thead><tbody><tr><td><code>.cpk</code></td><td>One matrix stream, finalized by <code>finish</code></td></tr><tr><td>Chunk</td><td>A group of rows with common coding models</td></tr><tr><td>Record</td><td>One row&#39;s compressed representation</td></tr><tr><td>Page</td><td>The unit used for aligned reads and cache frames</td></tr><tr><td>Cached row</td><td>A decoded input row in its stored dtype</td></tr></tbody></table><h2 id="four-column-spaces" tabindex="-1">Four column spaces <a class="header-anchor" href="#four-column-spaces" aria-label="Permalink to &quot;Four column spaces&quot;">​</a></h2><ol><li><strong>Source ids</strong> are the original matrix&#39;s column positions.</li><li><strong>Coded ids</strong> are column positions after a chunk&#39;s compression permutation.</li><li><strong>Standard ids</strong> belong to the application-defined vocabulary shared by matrices.</li><li><strong>Output ids</strong> are positions in a schema&#39;s output panel.</li></ol><p>Storage reads normally restore source order. A loader takes a source-to-standard map for each matrix and an output-to-standard list for each schema. It composes these maps when constructed. Name lookup and vocabulary construction remain with the application.</p><h2 id="cells-positions-accesses-and-batches" tabindex="-1">Cells, positions, accesses, and batches <a class="header-anchor" href="#cells-positions-accesses-and-batches" aria-label="Permalink to &quot;Cells, positions, accesses, and batches&quot;">​</a></h2><p>A <code>CellId</code> is a global <code>u32</code> row id assigned by a data source. A position is a logical place in the requested sequence and can refer to a cell more than once. With <code>S</code> output schemas, every position has <code>S</code> accesses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>access k -&gt; position k / S, schema k % S</span></span>
<span class="line"><span></span></span>
<span class="line"><span>position 0          position 1          position 2</span></span>
<span class="line"><span>schema 0 schema 1   schema 0 schema 1   schema 0 schema 1</span></span></code></pre></div><p>An output slot collects every schema&#39;s output for up to <code>slot_cells</code> consecutive positions. A batch is a lease on a completed slot. The last batch may have fewer rows. The schemas of a position may request the same cell or different cells.</p><h2 id="bounded-output-and-planned-reuse" tabindex="-1">Bounded output and planned reuse <a class="header-anchor" href="#bounded-output-and-planned-reuse" aria-label="Permalink to &quot;Bounded output and planned reuse&quot;">​</a></h2><p>The output ring has a fixed number of slots. A producer cannot overwrite a slot while a consumer holds its lease. Slow consumption applies backpressure.</p><p>A cache plan assigns input pages and decoded input rows to frames over intervals of accesses. Workers execute those reads, waits, and decodes. <code>Planning::None</code> disables planned caching but still uses worker-private I/O buffers and the output ring.</p><p>The output ring, the planned cache, and the operating system&#39;s page cache serve different purposes. See <a href="/cellpack-docs/rust/docs/performance.html">memory and performance</a> for their budgets.</p>`,16)])])}const m=a(n,[["render",d]]);export{h as __pageData,m as default};
